-/* LR walk: the controls/action/parse-stack panels above the step-history table stay pinned in
-   view — only the table itself scrolls, so the stepper stays reachable no matter how long the
-   trace is. lab__panel's own overflow is turned off in favor of lab__walk-history's, or the two
-   scroll containers would fight each other. */
+/* LR walk owns its own split scroll regions, so the panel's overflow is disabled here instead of
+   competing with the parse-tree/state panes. */
 .lab__panel--walk {
   display: flex;
   flex-direction: column;
   min-height: 0;
   overflow: hidden;
 }
 .lab__walk {
-  display: flex;
-  flex-direction: column;
+  display: grid;
+  grid-template-columns: minmax(280px, 1fr) minmax(320px, 0.78fr);
+  gap: 18px;
   min-height: 0;
   flex: 1 1 auto;
 }
-.lab__walk-history {
-  flex: 1 1 auto;
-  min-height: 40px;
-  overflow-y: auto;
-}
-/* The "# action" header row stays pinned at the top of the scrolling step-history table too, not
-   just the panels above it — sticky needs an opaque background (matching .lab's own, since
-   .lab__panel itself sets none) or scrolled-past rows would show through under the header text. */
-.lab__walk-history thead th {
-  position: sticky;
-  top: 0;
-  background: var(--bg);
-  z-index: 1;
+.lab__walk-tree,
+.lab__walk-state {
+  min-width: 0;
+  min-height: 0;
+}
+.lab__walk-tree {
+  overflow: auto;
+  border-right: 1px solid var(--border);
+  padding-right: 18px;
+}
+.lab__walk-state {
+  display: flex;
+  flex-direction: column;
+  overflow: auto;
 }
 .lab__empty {
   color: var(--fg-faint);
