-.lab__walk-action {
-  font-family: var(--font-mono);
-  font-size: 13px;
-  padding: 10px 14px;
-  border: 1px solid var(--border);
-  border-radius: var(--radius, 6px);
-  background: var(--bg-1);
-  margin-bottom: 14px;
-  flex: none;
-}
 .lab__walk-panes {
-  display: grid;
-  grid-template-columns: 1fr 1fr;
-  gap: 14px;
-  margin-bottom: 18px;
-  /* A long input can wrap the parse-stack/remaining-input chips across many lines — capping this
-     region and letting it scroll internally keeps the step-history table from being squeezed down
-     to nothing below it. flex:none for the same reason as .lab__walk-controls above: making this
-     ALSO flex-shrinkable sounds fairer (share the deficit with history instead of dumping it all
-     on history), but flex's shrink math weights by flex-basis, and an auto/content basis on a
-     scrolling item like history is its full (often much larger than visible) content height — that
-     made panes shrink to its floor even on a perfectly comfortable default-sized drawer. A modest
-     static cap keeps the common case unaffected while still leaving history a real (if tight)
-     minimum in the pathological very-long-input case. */
-  max-height: 70px;
-  overflow-y: auto;
-  flex: none;
+  display: flex;
+  flex-direction: column;
+  gap: 16px;
+  min-height: 0;
 }
 .lab__walk-chips {
   display: flex;
